        expenses = self.env['hr.expense'].browse(expense_ids)
        accessible_user_expense_ids = set(expenses._filtered_access('read').filtered(
            lambda e: e.state in {'draft', 'submitted'} and e.employee_id.user_id == self.env.user
        ).ids)
        blocked_expense_ids = []
